window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5cf74c55e468aa0b"]={"versions": [{"id": "FIG-5cf74c55e468aa0b", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Elektronisches Hardware-Prinzipschaltbild / Schaltungskonzept (Circuit Concept Schematic).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Schicht der ECU-Abstraktion (<em>ECU Abstraction Layer</em>), Modul <strong><code>IoHwAb</code></strong> (I/O Hardware Abstraction gemäß <code>RS_BRF_01080</code> und <code>SRS_IoHwAb_12242</code>).\n</li><li><strong>Technischer Zweck:</strong> Referenztopologie zur Rücklesediagnose digitaler High-Side-Schaltausgänge über einen analogen Überwachungspfad (<em>Analogue Monitor Line</em> via ADC). Ermöglicht die Erkennung, Differenzierung und Plausibilisierung von Leitungs- und Lastfehlern (<em>Short to Ground</em>, <em>Short to Battery</em>, <em>Open Load</em>, <em>Stuck-at-Defekte</em> des Treibers).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Hardware-Entitäten &amp; Schaltungselemente:</strong>\n<ul class=\"fig-list\"><li><code>+Ubat</code>: Primäres Versorgungsspannungs-Potenzial (Fahrzeug-Bordnetz/Batterie).\n</li><li><strong>High-Side-Schalter (oberer Block):</strong> Halbleiter-Schaltstufe (MOSFET / Smart Power Switch), schaltet <code>+Ubat</code> auf den Lastknoten.\n</li><li><code>Control</code>: Digitale Ansteuerleitung, verbunden mit dem Gate des Halbleiters; physikalisch angebunden an einen Mikrocontroller-Pin (DIO/PWM).\n</li><li><code>Load</code>: Elektrische Last (Aktor, Spule, Beleuchtung etc.) gegen Masse; vorgeschaltet ist ein Leitungs-/Sicherungs- oder Shunt-Element (gestrichelter Kasten).\n</li><li><strong>Spannungsteiler (unterer Block):</strong> Zwei ohmsche Präzisionswiderstände in Reihe gegen Schaltungsmasse (GND) am geschalteten Lastknoten zur Pegelanpassung (<code>+Ubat</code> auf den ADC-Eingangsbereich, z. B. 0–5 V bzw. 0–3,3 V).\n</li><li><code>analog Monitor</code>: Analoges Rücklesesignal vom Mittelabgriff des Spannungsteilers auf einen ADC-Kanal des Mikrocontrollers.\n</li></ul>\n</li><li><strong>AUTOSAR BSW-Zuordnung &amp; Schnittstellenbeziehungen:</strong>\n<ul class=\"fig-list\"><li><strong>MCAL-Treiber:</strong>\n<ul class=\"fig-list\"><li><code>Dio</code> (<code>Dio_WriteChannel</code>) bzw. <code>Pwm</code> (<code>Pwm_SetDutyCycle</code>): Treibt das Signal <code>Control</code>.\n</li><li><code>Adc</code> (<code>Adc_ReadGroup</code> / <code>Adc_GetStreamLastPointer</code>): Tastet <code>analog Monitor</code> ab.\n</li></ul>\n</li><li><strong><code>IoHwAb</code>:</strong> Aggregiert den digitalen Aktor-Pfad und den analogen Sensor-Pfad zu einer logischen Diagnose- und Steuerungs-Entität.\n</li><li><strong>Diagnose- &amp; Anbindungsschicht:</strong>\n<ul class=\"fig-list\"><li><code>Dem</code> (<code>Dem_SetEventStatus</code>): Meldet qualifizierte elektrische Fehler an den Diagnose-Stack.\n</li><li><code>Rte</code> / SW-C: Stellt der Applikation gekapselte Interfaces zur Verfügung (z. B. <code>SetDigitalOutput</code>, <code>GetOutputDiagnosticStatus</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Schaltanforderung:</strong> Eine SW-C fordert über die RTE das Schalten des Ausgangs an; <code>IoHwAb</code> steuert via <code>Dio</code> oder <code>Pwm</code> die Leitung <code>Control</code> an (Transistor leitend oder sperrend).\n</li><li><strong>Einschwingphase &amp; Entkopplung:</strong> Berücksichtigung einer definierten Totzeit (Hardware-RC-Filterung des Spannungsteilers sowie Schaltzeit des Halbleiters), um Transienten und EMV-Störungen auszublenden.\n</li><li><strong>Analoge Messwerterfassung:</strong>\n<ul class=\"fig-list\"><li>Synchrone Abtastung (z. B. timer- oder PWM-getriggert via ADC-Hardware-Trigger) oder asynchrone zyklische Erfassung über <code>Adc_StartGroupConversion()</code>.\n</li><li>Einlesen des ADC-Rohwerts an <code>analog Monitor</code>.\n</li></ul>\n</li><li><strong>Zustands- &amp; Fehlerklassifikation im <code>IoHwAb</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Schalter AUS (High-Side gesperrt):</strong>\n<ul class=\"fig-list\"><li>U_Monitor ≈ 0\\,V: Normalzustand (Last zieht Knoten auf Masse).\n</li><li>U_Monitor ≈ U_bat_scaled: <em>Short to Battery</em> (Kurzschluss nach Dauerplus) oder <em>Open Load</em> (bei interner Pull-up-Diagnosestromquelle).\n</li></ul>\n</li><li><strong>Schalter EIN (High-Side leitend):</strong>\n<ul class=\"fig-list\"><li>U_Monitor ≈ U_bat_scaled: Normalzustand (Nennspannung liegt an der Last an).\n</li><li>U_Monitor ≈ 0\\,V: <em>Short to Ground</em> (Kurzschluss nach Masse) oder Schalter defekt (<em>Stuck-at-Low</em> / Überstromabschaltung des Treibers).\n</li><li>0 &lt; U_Monitor &lt; U_bat_scaled: Erhöhter Übergangswiderstand / Übergangsfehler.\n</li></ul>\n</li></ul>\n</li><li><strong>Fehlerentprellung &amp; Event-Meldung:</strong> Nach Erreichen der Entprellschwellen (Debounce Counter) Aufruf von <code>Dem_SetEventStatus(EventId, DEM_EVENT_STATUS_FAILED)</code> bzw. <code>PASSED</code>.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Treiber- &amp; BSW-Konfiguration (<code>IoHwAb</code>):</strong>\n<ul class=\"fig-list\"><li>Parametrierung der Verknüpfung von <code>IoHwAbDigitalOutput</code> mit dem korrespondierenden <code>IoHwAbAnalogInput</code>.\n</li><li>Exakte Kalibrierung der Spannungsteiler-Verhältnisse (R_1, R_2) sowie der Schwellwerte für Batterietoleranzen (U_bat,min bis U_bat,max) in der BSW-Konfiguration.\n</li></ul>\n</li><li><strong>Timing- &amp; Synchronisations-Constraints:</strong>\n<ul class=\"fig-list\"><li>Bei PWM-getriebenen Ausgängen ist zwingend eine phasenstarre ADC-Triggerung (Cross-Triggering zwischen PWM-Timer und ADC) erforderlich; Abtastung darf nur im stabilen High- bzw. Low-Fenster erfolgen.\n</li></ul>\n</li><li><strong>Applikationsentkopplung:</strong>\n<ul class=\"fig-list\"><li>Die Applikations-SW-C darf keine Kenntnis über den physischen ADC-Kanal oder das Teilerverhältnis besitzen; sie konsumiert ausschließlich qualifizierte Status-Enums gemäß AUTOSAR-Port-Schnittstelle.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-67cf4b67a64b7a46", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Elektronisches Hardware-Prinzipschaltbild / Schaltungskonzept (Circuit Concept Schematic).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Schicht der ECU-Abstraktion (<em>ECU Abstraction Layer</em>), Modul <strong><code>IoHwAb</code></strong> (I/O Hardware Abstraction gemäß <code>RS_BRF_01080</code> und <code>SRS_IoHwAb_12242</code>).\n</li><li><strong>Technischer Zweck:</strong> Referenztopologie zur Rücklesediagnose digitaler High-Side-Schaltausgänge über einen analogen Überwachungspfad (<em>Analogue Monitor Line</em> via ADC). Ermöglicht die Erkennung, Differenzierung und Plausibilisierung von Leitungs- und Lastfehlern (<em>Short to Ground</em>, <em>Short to Battery</em>, <em>Open Load</em>, <em>Stuck-at-Defekte</em> des Treibers).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Hardware-Entitäten &amp; Schaltungselemente:</strong>\n<ul class=\"fig-list\"><li><code>+Ubat</code>: Primäres Versorgungsspannungs-Potenzial (Fahrzeug-Bordnetz/Batterie).\n</li><li><strong>High-Side-Schalter (oberer Block):</strong> Halbleiter-Schaltstufe (MOSFET / Smart Power Switch), schaltet <code>+Ubat</code> auf den Lastknoten.\n</li><li><code>Control</code>: Digitale Ansteuerleitung, verbunden mit dem Gate des Halbleiters; physikalisch angebunden an einen Mikrocontroller-Pin (DIO/PWM).\n</li><li><code>Load</code>: Elektrische Last (Aktor, Spule, Beleuchtung etc.) gegen Masse; vorgeschaltet ist ein Leitungs-/Sicherungs- oder Shunt-Element (gestrichelter Kasten).\n</li><li><strong>Spannungsteiler (unterer Block):</strong> Zwei ohmsche Präzisionswiderstände in Reihe gegen Schaltungsmasse (GND) am geschalteten Lastknoten zur Pegelanpassung (<code>+Ubat</code> auf den ADC-Eingangsbereich, z. B. 0–5 V bzw. 0–3,3 V).\n</li><li><code>analog Monitor</code>: Analoges Rücklesesignal vom Mittelabgriff des Spannungsteilers auf einen ADC-Kanal des Mikrocontrollers.\n</li></ul>\n</li><li><strong>AUTOSAR BSW-Zuordnung &amp; Schnittstellenbeziehungen:</strong>\n<ul class=\"fig-list\"><li><strong>MCAL-Treiber:</strong>\n<ul class=\"fig-list\"><li><code>Dio</code> (<code>Dio_WriteChannel</code>) bzw. <code>Pwm</code> (<code>Pwm_SetDutyCycle</code>): Treibt das Signal <code>Control</code>.\n</li><li><code>Adc</code> (<code>Adc_ReadGroup</code> / <code>Adc_GetStreamLastPointer</code>): Tastet <code>analog Monitor</code> ab.\n</li></ul>\n</li><li><strong><code>IoHwAb</code>:</strong> Aggregiert den digitalen Aktor-Pfad und den analogen Sensor-Pfad zu einer logischen Diagnose- und Steuerungs-Entität.\n</li><li><strong>Diagnose- &amp; Anbindungsschicht:</strong>\n<ul class=\"fig-list\"><li><code>Dem</code> (<code>Dem_SetEventStatus</code>): Meldet qualifizierte elektrische Fehler an den Diagnose-Stack.\n</li><li><code>Rte</code> / SW-C: Stellt der Applikation gekapselte Interfaces zur Verfügung (z. B. <code>SetDigitalOutput</code>, <code>GetOutputDiagnosticStatus</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Schaltanforderung:</strong> Eine SW-C fordert über die RTE das Schalten des Ausgangs an; <code>IoHwAb</code> steuert via <code>Dio</code> oder <code>Pwm</code> die Leitung <code>Control</code> an (Transistor leitend oder sperrend).\n</li><li><strong>Einschwingphase &amp; Entkopplung:</strong> Berücksichtigung einer definierten Totzeit (Hardware-RC-Filterung des Spannungsteilers sowie Schaltzeit des Halbleiters), um Transienten und EMV-Störungen auszublenden.\n</li><li><strong>Analoge Messwerterfassung:</strong>\n<ul class=\"fig-list\"><li>Synchrone Abtastung (z. B. timer- oder PWM-getriggert via ADC-Hardware-Trigger) oder asynchrone zyklische Erfassung über <code>Adc_StartGroupConversion()</code>.\n</li><li>Einlesen des ADC-Rohwerts an <code>analog Monitor</code>.\n</li></ul>\n</li><li><strong>Zustands- &amp; Fehlerklassifikation im <code>IoHwAb</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Schalter AUS (High-Side gesperrt):</strong>\n<ul class=\"fig-list\"><li>U_Monitor ≈ 0\\,V: Normalzustand (Last zieht Knoten auf Masse).\n</li><li>U_Monitor ≈ U_bat_scaled: <em>Short to Battery</em> (Kurzschluss nach Dauerplus) oder <em>Open Load</em> (bei interner Pull-up-Diagnosestromquelle).\n</li></ul>\n</li><li><strong>Schalter EIN (High-Side leitend):</strong>\n<ul class=\"fig-list\"><li>U_Monitor ≈ U_bat_scaled: Normalzustand (Nennspannung liegt an der Last an).\n</li><li>U_Monitor ≈ 0\\,V: <em>Short to Ground</em> (Kurzschluss nach Masse) oder Schalter defekt (<em>Stuck-at-Low</em> / Überstromabschaltung des Treibers).\n</li><li>0 &lt; U_Monitor &lt; U_bat_scaled: Erhöhter Übergangswiderstand / Übergangsfehler.\n</li></ul>\n</li></ul>\n</li><li><strong>Fehlerentprellung &amp; Event-Meldung:</strong> Nach Erreichen der Entprellschwellen (Debounce Counter) Aufruf von <code>Dem_SetEventStatus(EventId, DEM_EVENT_STATUS_FAILED)</code> bzw. <code>PASSED</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Treiber- &amp; BSW-Konfiguration (<code>IoHwAb</code>):</strong>\n<ul class=\"fig-list\"><li>Parametrierung der Verknüpfung von <code>IoHwAbDigitalOutput</code> mit dem korrespondierenden <code>IoHwAbAnalogInput</code>.\n</li><li>Exakte Kalibrierung der Spannungsteiler-Verhältnisse (R_1, R_2) sowie der Schwellwerte für Batterietoleranzen (U_bat,min bis U_bat,max) in der BSW-Konfiguration.\n</li></ul>\n</li><li><strong>Timing- &amp; Synchronisations-Constraints:</strong>\n<ul class=\"fig-list\"><li>Bei PWM-getriebenen Ausgängen ist zwingend eine phasenstarre ADC-Triggerung (Cross-Triggering zwischen PWM-Timer und ADC) erforderlich; Abtastung darf nur im stabilen High- bzw. Low-Fenster erfolgen.\n</li></ul>\n</li><li><strong>Applikationsentkopplung:</strong>\n<ul class=\"fig-list\"><li>Die Applikations-SW-C darf keine Kenntnis über den physischen ADC-Kanal oder das Teilerverhältnis besitzen; sie konsumiert ausschließlich qualifizierte Status-Enums gemäß AUTOSAR-Port-Schnittstelle.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5cf74c55e468aa0b", "to": "FIG-67cf4b67a64b7a46", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
